	private static Set<String> readProbeValues(SailConnection connection) {
		Set<String> values = new HashSet<>();
		try (CloseableIteration<? extends Statement> statements = connection.getStatements(PROBE_SUBJECT,
				PROBE_PREDICATE, null, false)) {
			while (statements.hasNext()) {
				values.add(statements.next().getObject().stringValue());
			}
			return values;
		} catch (SailException failure) {
			throw new RuntimeException(failure);
		}
	}

